<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import {Upload,Plus,X} from 'lucide-svelte';
 import MailConfirm from './MailConfirm.svelte';
 import {validateFiles,fileBase64,droppedFiles,transferHasFiles} from './attachments';
 import {fileSize} from './files';
 let {ownId,folder,destination,disabled=false,existingNames=[],onUploaded,onBusyChange}:{ownId:string;folder:string|null;destination:string;disabled?:boolean;existingNames?:string[];onUploaded:()=>void;onBusyChange:(busy:boolean)=>void}=$props();
 let files=$state<File[]>([]),review=$state(false),busy=$state(false),drag=$state(false),error=$state(''),completed=$state<string[]>([]),behavior=$state('rename'),uploaded=$state(0),total=$state(0);
 let pending=$state<{id:string;name:string}|null>(null),pendingStatus=$state('unknown');let alive=true,input:HTMLInputElement;
 const key=$derived(JSON.stringify(['taut-files-upload',ownId]));
 const locked=$derived(busy||review||pendingStatus==='uploading');
 $effect(()=>onBusyChange(locked));
 function add(incoming:File[]){if(disabled||locked||pending)return;error='';try{validateFiles(files,incoming);files=[...files,...incoming];}catch(e){error=String(e).replace('Attach up to','Upload up to').replaceAll('per message','per upload').replace('Attachments must','Uploads must');}}
 function clearPending(id:string){try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value?.id===id)localStorage.removeItem(key);}catch{}if(alive){pending=null;pendingStatus='unknown';}}
 async function progress(){const target=pending;if(!target)return;try{const value=await invoke<{status:string;uploaded?:number;total?:number}>('files_upload_progress',{ownId,attemptId:target.id});if(!alive||pending?.id!==target.id)return;if(value.status==='unknown'&&busy)return;pendingStatus=value.status;uploaded=value.uploaded??0;total=value.total??0;if(value.status==='complete'&&!busy){error='';const index=files.findIndex(file=>file.name===target.name);if(index>=0)files=files.filter((_,i)=>i!==index);completed=[...completed,`${target.name} finished uploading. No retry was sent.`];clearPending(target.id);onUploaded();}}catch{if(alive&&pending?.id===target.id&&!busy)pendingStatus='unknown';}}
 onMount(()=>{try{const value=JSON.parse(localStorage.getItem(key)||'null');if(value){pending={id:typeof value.id==='string'?value.id:'unknown',name:typeof value.name==='string'?value.name:'Previous file'};void progress();}}catch{error='Previous upload state could not be read. Check OneDrive before uploading.';}const timer=setInterval(()=>{if(pending)void progress();},500);return ()=>clearInterval(timer);});
 onDestroy(()=>{alive=false;onBusyChange(false);});
 async function send(){if(busy||disabled||pending||!files.length)return;review=false;busy=true;error='';completed=[];let changed=false;const batch=[...files],target=folder,choice=behavior;
  try{for(const file of batch){if(!alive)return;const id=crypto.randomUUID();pending={id,name:file.name};pendingStatus='uploading';uploaded=0;total=file.size;
   // Reserve locally before any network write; a reload cannot silently repeat it.
   try{localStorage.setItem(key,JSON.stringify(pending));}catch{pending=null;pendingStatus='unknown';throw Error('Upload could not be recorded locally. Nothing was sent.');}
   const data=await fileBase64(file);if(!alive){clearPending(id);return;}
   const result=await invoke<{status:string;item?:{name:string};error?:string}>('files_upload',{ownId,attemptId:id,folder:target,name:file.name,data,behavior:choice});
   if(result.status!=='complete'){if(alive){pendingStatus='unconfirmed';error=result.error||'Upload was not confirmed. Check OneDrive before retrying.';}return;}
   clearPending(id);changed=true;if(!alive)return;completed=[...completed,`Uploaded: ${result.item?.name||file.name}`];files=files.filter(selected=>selected!==file);
  }}catch(e){if(alive){error=String(e);if(pending)pendingStatus='unconfirmed';}}finally{if(alive){busy=false;if(changed)onUploaded();}}
 }
 function drop(event:DragEvent){if(!transferHasFiles(event.dataTransfer))return;event.preventDefault();event.stopPropagation();drag=false;try{add(droppedFiles(event.dataTransfer!));}catch(e){error=String(e);}}
</script>
<section class="upload" class:dragging={drag} aria-label="Upload files" ondragover={event=>{if(transferHasFiles(event.dataTransfer)){event.preventDefault();event.stopPropagation();drag=!disabled&&!locked&&!pending;if(event.dataTransfer)event.dataTransfer.dropEffect=drag?'copy':'none';}}} ondragleave={()=>drag=false} ondrop={drop}>
 <div class="upload-heading"><div><strong><Upload size={17}/>Upload to this folder</strong><p>{disabled?'Return to a folder to choose an upload destination.':'Drop individual files here, or choose files. Nothing uploads until you review and confirm.'}</p></div><button disabled={disabled||locked||!!pending} onclick={()=>input.click()}><Plus size={15}/>Choose files</button><input bind:this={input} type="file" multiple hidden aria-label="Choose OneDrive upload files" disabled={disabled||locked||!!pending} onchange={event=>{add(Array.from(event.currentTarget.files??[]));event.currentTarget.value='';}}/></div>
 {#if files.length}<ul>{#each files as file,i}<li><span>{file.name} <small>· {fileSize(file.size)}{existingNames.some(name=>name.toLowerCase()===file.name.toLowerCase())?' · Name exists in loaded folder':''}</small></span><button aria-label={`Remove ${file.name} from upload`} disabled={locked||!!pending} onclick={()=>files=files.filter((_,index)=>index!==i)}><X size={14}/></button></li>{/each}</ul><div class="upload-options"><label>If a name already exists<select aria-label="Duplicate filenames" disabled={locked||!!pending} bind:value={behavior}><option value="rename">Keep both (OneDrive renames the new file)</option><option value="fail">Stop on conflict</option></select></label><button class="primary" disabled={disabled||locked||!!pending} onclick={()=>review=true}>Review upload</button></div>{/if}
 {#if pending}<div class="pending" role="status"><strong>{pendingStatus==='uploading'?`Uploading ${pending.name}…`:`Check OneDrive for ${pending.name}`}</strong>{#if pendingStatus==='uploading'}<progress aria-label="Upload progress" value={uploaded} max={total||1}></progress><small>{fileSize(uploaded)} of {fileSize(total)}</small><p>Leaving Files does not cancel the file already uploading.</p>{:else}<p>The previous upload may have completed. No automatic retry will be sent.</p><button disabled={busy} onclick={()=>pending&&clearPending(pending.id)}>I checked OneDrive</button>{/if}</div>{/if}
 {#if error}<p class="error" role="alert">{error}</p>{/if}{#if completed.length}<div role="status">{#each completed as message}<p>{message}</p>{/each}</div>{/if}
 <small>Up to 5 files · 10 MB each · 25 MB total. Existing files are never overwritten.</small>
</section>
{#if review}<MailConfirm title="Upload these files to OneDrive?" confirmLabel="Upload files" onClose={()=>review=false} onConfirm={send}><p>Destination: <strong>{destination}</strong></p><ul>{#each files as file}<li>{file.name} · {fileSize(file.size)}</li>{/each}</ul><p>{behavior==='rename'?'Duplicate names: keep both. OneDrive will rename the new file.':'Duplicate names: stop on conflict.'}</p><p>This uploads the selected files to your OneDrive. Files use this folder’s existing access permissions. TAUT does not change sharing or send a message.</p></MailConfirm>{/if}
<style>.upload{border:1px dashed var(--border-strong);border-radius:9px;padding:14px 16px;margin:0 0 20px;background:var(--surface-panel)}.dragging{border-color:var(--accent);background:var(--accent-soft)}.upload-heading,.upload-options{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.upload-heading strong{display:flex;align-items:center;gap:8px;font-size:13px}.upload p{font-size:12px;color:var(--text-secondary);line-height:1.5;margin:8px 0}.upload small{font-size:10px;color:var(--text-secondary)}button{font:inherit;color:var(--accent);display:inline-flex;align-items:center;gap:6px;padding:8px 10px;border:1px solid var(--border-strong);border-radius:6px;font-size:12px;cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:var(--accent);color:var(--text-on-accent)}ul{list-style:none;padding:0;margin:12px 0}li{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 0;font-size:12px;overflow-wrap:anywhere}li span{min-width:0}.upload-options{margin:12px 0}label{display:grid;gap:6px;font-size:11px;color:var(--text-secondary)}select{padding:7px;font:inherit;background:var(--surface-raised);color:var(--text-primary);border:1px solid var(--border-strong);border-radius:5px;max-width:100%}.pending{padding:10px 0;font-size:12px}.pending progress{display:block;width:100%;margin:10px 0;accent-color:var(--accent)}.upload .error{color:var(--error)}button:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}</style>
